#include <stdio.h>

struct Item {
    const char *name;
    int price;
};

int main() {
    struct Item items[] = {{"pen", 15}, {"book", 120}, {"eraser", 5}, {"bag", 450}};
    for (int i = 0; i < 4; i++) {
        for (int j = i + 1; j < 4; j++) {
            if (items[i].price > items[j].price) {
                struct Item temp = items[i];
                items[i] = items[j];
                items[j] = temp;
            }
        }
    }
    for (int i = 0; i < 4; i++) {
        printf("%s %d\n", items[i].name, items[i].price);
    }
    return 0;
}
